async function main() {
  if (!process.env.DATABASE_URL) { console.error("\u2717 DATABASE_URL manquant"); process.exit(1); }
  let updated = 0, added = 0, skipped = 0, missing = 0;

  // --- Phase 1 : descriptions statiques (DESC puis DESC_INCERTAIN) ---------
  const TABLES = [DESC];
  if (process.env.SKIP_INCERTAIN === "1") {
    console.log("Palier 3 (DESC_INCERTAIN) ignoré (SKIP_INCERTAIN=1).");
  } else {
    TABLES.push(DESC_INCERTAIN);
  }
  if (process.env.SKIP_RECUEILS === "1") {
    console.log("Recueils annuels (DESC_RECUEILS) ignorés (SKIP_RECUEILS=1).");
  } else {
    TABLES.push(DESC_RECUEILS);
  }
  const STATIC = {};
  for (const t of TABLES)
    for (const [f, byIdx] of Object.entries(t))
      STATIC[f] = Object.assign({}, STATIC[f], byIdx);

  for (const [file, byIdx] of Object.entries(STATIC)) {
    const { rows } = await pool.query(
      "SELECT id, questions FROM annales WHERE image_url = $1 LIMIT 1", ["annales-pdf/" + file]);
    if (!rows.length) { missing++; continue; }
    let qs = rows[0].questions;
    if (typeof qs === "string") qs = JSON.parse(qs || "[]");
    if (!Array.isArray(qs) || !qs.length) { missing++; continue; }
    let changed = false;
    for (const [idxStr, desc] of Object.entries(byIdx)) {
      const i = Number(idxStr);
      if (!qs[i]) continue;
      if (qs[i].figure_desc) { skipped++; continue; }
      qs[i].figure_desc = desc; changed = true; added++;
    }
    if (changed) {
      await pool.query("UPDATE annales SET questions = $1 WHERE id = $2", [JSON.stringify(qs), rows[0].id]);
      updated++;
    }
  }
  console.log(`\nPhase 1 (statique) : ${added} description(s) sur ${updated} sujet(s), ${skipped} d\u00e9j\u00e0 pr\u00e9sente(s), ${missing} introuvable(s).`);

  // --- Phase 2 : remplissage automatique d'apr\u00e8s les donn\u00e9es de l'\u00e9nonc\u00e9 ---
  if (process.env.AUTO_FILL === "0") {
    console.log("Phase 2 (auto) d\u00e9sactiv\u00e9e (AUTO_FILL=0).");
    await pool.end();
    return;
  }
  let autoAdded = 0, autoSujets = 0, autoSkip = 0;
  const { rows: allRows } = await pool.query("SELECT id, image_url, questions FROM annales");
  for (const row of allRows) {
    let qs = row.questions;
    if (typeof qs === "string") { try { qs = JSON.parse(qs || "[]"); } catch { continue; } }
    if (!Array.isArray(qs) || !qs.length) continue;
    let changed = false;
    for (let i = 0; i < qs.length; i++) {
      const q = qs[i];
      if (!q || typeof q !== "object") continue;
      if (q.figure_desc) { autoSkip++; continue; }     // idempotent : jamais r\u00e9\u00e9crit
      const statement = extractStatement(q);
      if (!statement) continue;
      const desc = buildFigureDesc(statement);
      if (!desc) continue;                              // pas de renvoi clair \u00e0 une figure
      q.figure_desc = desc; changed = true; autoAdded++;
    }
    if (changed) {
      await pool.query("UPDATE annales SET questions = $1 WHERE id = $2", [JSON.stringify(qs), row.id]);
      autoSujets++;
    }
  }
  console.log(`Phase 2 (auto)     : ${autoAdded} description(s) sur ${autoSujets} sujet(s), ${autoSkip} d\u00e9j\u00e0 pr\u00e9sente(s).`);
  console.log(`\nTermin\u00e9.`);
  await pool.end();
}

/* --- Phase 2 : utilitaires ------------------------------------------------
   Reproduit la m\u00e9thode des descriptions statiques (« d'apr\u00e8s les donn\u00e9es de
   l'\u00e9nonc\u00e9 ») mais \u00e0 partir du texte r\u00e9el stock\u00e9 en base, pour couvrir les
   questions non list\u00e9es dans DESC. Volontairement prudent. */

// Champs susceptibles de contenir l'\u00e9nonc\u00e9, par ordre de pr\u00e9f\u00e9rence.
const STATEMENT_KEYS = ["enonce", "enonce_html", "question", "texte", "text",
  "consigne", "intitule", "statement", "content", "corps", "body"];
// Champs \u00e0 ne jamais lire (r\u00e9ponses / m\u00e9tadonn\u00e9es) pour ne pas polluer la figure.
const SKIP_KEYS = /^(figure_desc|reponse|reponses|answer|answers|correction|corrige|corrig\u00e9|solution|bareme|bar\u00e8me|note|points?|id|_id|index|idx|type|image|image_url|url|slug|niveau|competence|competences|theme|themes|chapitre|tags?)$/i;

function stripHtml(s) {
  return String(s).replace(/<[^>]+>/g, " ").replace(/&[a-z]+;/gi, " ");
}

// R\u00e9cup\u00e8re le texte d'\u00e9nonc\u00e9 d'une question, quel que soit le sch\u00e9ma.
function extractStatement(q) {
  for (const k of STATEMENT_KEYS) {
    if (typeof q[k] === "string" && q[k].trim()) return stripHtml(q[k]);
  }
  // repli : concat\u00e9nation des cha\u00eenes du niveau sup\u00e9rieur, hors champs r\u00e9ponse.
  const parts = [];
  for (const [k, v] of Object.entries(q)) {
    if (SKIP_KEYS.test(k)) continue;
    if (typeof v === "string" && v.trim().length > 8) parts.push(stripHtml(v));
    else if (Array.isArray(v)) for (const it of v) {
      if (typeof it === "string" && it.trim().length > 8) parts.push(stripHtml(it));
    }
  }
  const joined = parts.join(" ").trim();
  return joined.length > 12 ? joined : "";
}

// Renvoi explicite \u00e0 une figure dessin\u00e9e dans le sujet.
const FIGURE_CUE = /(ci-contre|ci-dessous|ci-apr\u00e8s|ci-joint|figure ci|la figure|le sch\u00e9ma|un sch\u00e9ma|repr\u00e9sent\u00e9(?:e|s|es)? ci|repr\u00e9sente ci|voir figure|sur la figure|comme (?:indiqu\u00e9|sur la figure)|croquis|rep\u00e8re orthonorm|rep\u00e8re orthogonal|graphique ci-)/i;

// Mots-cl\u00e9s g\u00e9om\u00e9triques / de figure servant \u00e0 s\u00e9lectionner les phrases utiles.
const GEOM = /(triangle|rectangle|carr\u00e9|carr\u00e9e|losange|parall\u00e9logramme|trap\u00e8ze|cercle|disque|diam\u00e8tre|rayon|c\u00f4ne|cylindre|sph\u00e8re|pyramide|prisme|pav\u00e9|hexagone|octogone|polygone|segment|droite|arc|angle|align\u00e9s?|align\u00e9es?|parall\u00e8les?|perpendiculaire|isoc\u00e8le|\u00e9quilat\u00e9ral|hauteur|c\u00f4t\u00e9|c\u00f4t\u00e9s|milieu|sommet|diagonale|bissectrice|m\u00e9diane|m\u00e9diatrice|tangente|abscisse|ordonn\u00e9e|rep\u00e8re|centre|\bAB\b|\bBC\b|\bAC\b|\bcm\b|\bmm\b|\bdm\b|\bkm\b|=\s*\d|\d\s*(?:cm|mm|dm|m|km|\u00b0))/i;

// D\u00e9coupe l'\u00e9nonc\u00e9 en segments (retours \u00e0 la ligne + ponctuation forte).
function segments(txt) {
  return txt
    .replace(/\r/g, "\n")
    .split(/\n+|(?<=[.;:!?])\s+/)
    .map(s => s.replace(/\s+/g, " ").trim())
    .filter(s => s.length >= 3);
}

// Construit la description au format des entr\u00e9es statiques, ou "" si rien de sûr.
function buildFigureDesc(statement) {
  if (!FIGURE_CUE.test(statement)) return "";        // pas de figure \u00e9vidente -> on s'abstient
  const segs = segments(statement);
  const kept = [];
  const seen = new Set();
  for (const s of segs) {
    if (!(GEOM.test(s) || FIGURE_CUE.test(s))) continue;
    const key = s.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    kept.push(s);
    if (kept.length >= 8) break;
  }
  if (kept.length < 1) return "";
  // Trop peu d'indices g\u00e9om\u00e9triques : on reste prudent et on n'invente pas.
  const geomCount = kept.filter(s => GEOM.test(s)).length;
  if (geomCount < 1) return "";
  let body = kept.join(" ; ");
  if (body.length > 700) body = body.slice(0, 697).replace(/\s+\S*$/, "") + "…";
  if (!/[.?!…]$/.test(body)) body += ".";
  return "Figure décrite d'après les données de l'énoncé : " + body;
}

main().catch(e => { console.error("Erreur :", e.message); process.exit(1); });
